import { readFile } from "node:fs/promises";
import path from "node:path";
import index from "@/content/prayag/blog/index.json";

// Content generated by scripts/prayag-blog-import.py from the captured prayagindia.com blog.

export interface BlogListItem {
  slug: string;
  year: string;
  /** Unix seconds; the source sorts by this (data-date). */
  timestamp: number;
  /** Display date as on the source, e.g. "19-Oct-2026". */
  date: string;
  title: string;
  image: string;
  imageAlt: string;
}

export interface RelatedPost {
  slug: string | null;
  href: string;
  image: string;
  imageAlt: string;
  title: string;
  excerpt: string;
}

export interface BlogArticle {
  slug: string;
  title: string;
  published: string;
  timestamp: number;
  metaTitle: string | null;
  description: string | null;
  bannerImage: string;
  bannerAlt: string;
  /** Source article HTML, sanitised at import (no scripts/iframes/handlers, links rewritten). */
  bodyHtml: string;
  related: RelatedPost[];
}

export const blogIndex: BlogListItem[] = index;

const slugs = new Set(blogIndex.map((post) => post.slug));

export function isBlogSlug(slug: string) {
  return slugs.has(slug);
}

export async function getBlogArticle(slug: string): Promise<BlogArticle | null> {
  if (!isBlogSlug(slug)) return null;
  const file = path.join(process.cwd(), "src/content/prayag/blog/articles", `${slug}.json`);
  return JSON.parse(await readFile(file, "utf8")) as BlogArticle;
}
